// ---- lib/normalize.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Normalisation primitives.
// Everything that turns messy scraped text into a comparable value lives here.
// Pure functions only - no I/O - so the same code runs in tests, in n8n Code
// nodes (inlined by n8n/build.mjs) and in scripts.
// ---------------------------------------------------------------------------

const US_STATES = {
  alabama: 'AL', alaska: 'AK', arizona: 'AZ', arkansas: 'AR', california: 'CA',
  colorado: 'CO', connecticut: 'CT', delaware: 'DE', 'district of columbia': 'DC',
  florida: 'FL', georgia: 'GA', hawaii: 'HI', idaho: 'ID', illinois: 'IL',
  indiana: 'IN', iowa: 'IA', kansas: 'KS', kentucky: 'KY', louisiana: 'LA',
  maine: 'ME', maryland: 'MD', massachusetts: 'MA', michigan: 'MI', minnesota: 'MN',
  mississippi: 'MS', missouri: 'MO', montana: 'MT', nebraska: 'NE', nevada: 'NV',
  'new hampshire': 'NH', 'new jersey': 'NJ', 'new mexico': 'NM', 'new york': 'NY',
  'north carolina': 'NC', 'north dakota': 'ND', ohio: 'OH', oklahoma: 'OK',
  oregon: 'OR', pennsylvania: 'PA', 'rhode island': 'RI', 'south carolina': 'SC',
  'south dakota': 'SD', tennessee: 'TN', texas: 'TX', utah: 'UT', vermont: 'VT',
  virginia: 'VA', washington: 'WA', 'west virginia': 'WV', wisconsin: 'WI',
  wyoming: 'WY'
};

const STATE_CODES = new Set(Object.values(US_STATES));

// Legal-entity and decorative suffixes that must not make two rows look different.
const NAME_NOISE = [
  'llc', 'l l c', 'inc', 'inc.', 'incorporated', 'corp', 'corporation', 'co',
  'company', 'ltd', 'limited', 'plc', 'pllc', 'pc', 'pa', 'dds', 'md', 'dmd',
  'the', 'official', 'shop', 'store', 'usa', 'us'
];

function stripDiacritics(value) {
  return String(value ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '');
}

function collapseWhitespace(value) {
  return String(value ?? '').replace(/\s+/g, ' ').trim();
}

/** Display-safe business name: trimmed, de-emojied, single-spaced. */
function cleanBusinessName(value) {
  if (!value) return null;
  const cleaned = collapseWhitespace(
    stripDiacritics(value)
      .replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}\u{200D}]/gu, ' ')
      .replace(/[|•·–—]+/g, ' ')
  );
  return cleaned || null;
}

/**
 * Comparison key for a business name. Lowercase, no punctuation, no legal
 * suffixes, no filler words. "Glow Med Spa, LLC" and "glow medspa" collapse to
 * the same key, which is what the dedupe layer matches on.
 */
function normalizeBusinessName(value) {
  const base = cleanBusinessName(value);
  if (!base) return null;
  const tokens = base
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/[^a-z0-9\s]/g, ' ')
    .split(/\s+/)
    .filter(Boolean)
    .filter((t) => !NAME_NOISE.includes(t));
  // "med spa" -> "medspa", "hair salon" -> "hairsalon" is too aggressive; only
  // collapse the two-token forms that are genuinely written both ways.
  const joined = tokens.join(' ')
    .replace(/\bmed spa\b/g, 'medspa')
    .replace(/\bday spa\b/g, 'dayspa')
    .replace(/\be commerce\b/g, 'ecommerce');
  return joined || null;
}

/** Instagram handle without @, url wrapper, query string or trailing slash. */
function normalizeHandle(value) {
  if (!value) return null;
  let handle = String(value).trim();
  const urlMatch = handle.match(/instagram\.com\/([^/?#]+)/i);
  if (urlMatch) handle = urlMatch[1];
  handle = handle.replace(/^@+/, '').replace(/\/+$/, '').split('?')[0].trim().toLowerCase();
  if (!handle) return null;
  // Instagram handles: letters, numbers, periods, underscores, max 30 chars.
  if (!/^[a-z0-9._]{1,30}$/.test(handle)) return null;
  const reserved = new Set(['p', 'reel', 'reels', 'explore', 'stories', 'accounts', 'direct', 'tv']);
  if (reserved.has(handle)) return null;
  return handle;
}

function instagramUrl(handle) {
  const h = normalizeHandle(handle);
  return h ? `https://www.instagram.com/${h}/` : null;
}

/** Absolute, lowercase-host URL with tracking parameters removed. */
function normalizeUrl(value) {
  if (!value) return null;
  let raw = String(value).trim();
  if (!raw || raw === '-' || raw.toLowerCase() === 'n/a') return null;
  if (!/^https?:\/\//i.test(raw)) raw = `https://${raw}`;
  let url;
  try {
    url = new URL(raw);
  } catch {
    return null;
  }
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/i.test(url.hostname)) return null;
  for (const key of [...url.searchParams.keys()]) {
    if (/^(utm_|fbclid|gclid|mc_|ref|source)/i.test(key)) url.searchParams.delete(key);
  }
  url.hostname = url.hostname.toLowerCase();
  url.hash = '';
  const path = url.pathname.replace(/\/+$/, '');
  return `${url.protocol}//${url.hostname}${path}${url.search}`;
}

// Link-in-bio aggregators are not a website - they must never become a dedupe key.
const AGGREGATOR_DOMAINS = new Set([
  'linktr.ee', 'link.tree', 'beacons.ai', 'bio.link', 'linkin.bio', 'msha.ke',
  'taplink.cc', 'lnk.bio', 'solo.to', 'campsite.bio', 'linkpop.com', 'many.link',
  'instagram.com', 'facebook.com', 'm.facebook.com', 'business.facebook.com',
  'tiktok.com', 'youtube.com', 'twitter.com', 'x.com', 'wa.me', 'api.whatsapp.com',
  'g.page', 'goo.gl', 'maps.google.com', 'yelp.com', 'booksy.com', 'vagaro.com',
  'square.site', 'squareup.com', 'calendly.com', 'sites.google.com'
]);

function isAggregatorDomain(domain) {
  if (!domain) return false;
  const d = String(domain).toLowerCase().replace(/^www\./, '');
  return AGGREGATOR_DOMAINS.has(d);
}

/** Registrable-ish domain: host without www, aggregators rejected. */
function normalizeDomain(value) {
  const url = normalizeUrl(value);
  if (!url) return null;
  let host;
  try {
    host = new URL(url).hostname.toLowerCase().replace(/^www\./, '');
  } catch {
    return null;
  }
  if (isAggregatorDomain(host)) return null;
  return host;
}

/** US phone to E.164. Anything that is not a plausible US number returns null. */
function normalizePhone(value, defaultCountry = '1') {
  if (!value) return null;
  const raw = String(value);
  if (/ext|x\d{3,}/i.test(raw) === false && raw.trim().startsWith('+')) {
    const intl = raw.replace(/[^\d+]/g, '');
    if (/^\+\d{8,15}$/.test(intl)) return intl;
  }
  const digits = raw.replace(/\D/g, '');
  if (!digits) return null;
  let national = digits;
  if (national.length === 11 && national.startsWith('1')) national = national.slice(1);
  if (national.length !== 10) return null;
  if (/^[01]/.test(national)) return null;              // invalid NANP area code
  if (/^(\d)\1{9}$/.test(national)) return null;        // 5555555555 style junk
  return `+${defaultCountry}${national}`;
}

function normalizeEmail(value) {
  if (!value) return null;
  const email = String(value).trim().toLowerCase().replace(/^mailto:/, '');
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/.test(email)) return null;
  const local = email.split('@')[0];
  if (/^(noreply|no-reply|donotreply|postmaster|abuse|privacy)$/.test(local)) return null;
  return email;
}

/** Accepts "California", "california", "CA", "Calif." -> "CA". */
function normalizeState(value) {
  if (!value) return null;
  const raw = String(value).trim();
  const upper = raw.toUpperCase();
  if (STATE_CODES.has(upper)) return upper;
  const key = stripDiacritics(raw).toLowerCase().replace(/[^a-z\s]/g, '').trim();
  if (US_STATES[key]) return US_STATES[key];
  const prefix = Object.keys(US_STATES).find((name) => name.startsWith(key) && key.length >= 4);
  return prefix ? US_STATES[prefix] : null;
}

function normalizeCity(value) {
  if (!value) return null;
  const city = collapseWhitespace(stripDiacritics(value).replace(/[^\p{L}\s.'-]/gu, ' '));
  if (!city || city.length < 2) return null;
  return city
    .toLowerCase()
    .split(' ')
    .map((w) => (w.length > 2 || /^(st|ft)$/.test(w) ? w[0].toUpperCase() + w.slice(1) : w))
    .join(' ');
}

function slug(value) {
  return stripDiacritics(String(value ?? ''))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '')
    .slice(0, 40);
}

/** "12.3k" / "1,234" / "2.1M" -> integer. */
function parseCount(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? Math.round(value) : null;
  const raw = String(value).trim().toLowerCase().replace(/,/g, '').replace(/\s/g, '');
  const match = raw.match(/^([\d.]+)([km])?$/);
  if (!match) return null;
  const n = Number.parseFloat(match[1]);
  if (!Number.isFinite(n)) return null;
  const mult = match[2] === 'k' ? 1e3 : match[2] === 'm' ? 1e6 : 1;
  return Math.round(n * mult);
}

function toIsoDate(value) {
  if (!value) return null;
  const d = value instanceof Date ? value : new Date(value);
  return Number.isNaN(d.getTime()) ? null : d.toISOString();
}

function daysSince(value, now = new Date()) {
  const iso = toIsoDate(value);
  if (!iso) return null;
  return Math.floor((now.getTime() - new Date(iso).getTime()) / 86400000);
}

/**
 * Normalise a raw discovery row into the canonical lead shape every downstream
 * step expects. Unknown provider fields are kept under `raw`.
 */
function normalizeRawLead(raw = {}) {
  const pick = (...keys) => {
    for (const k of keys) {
      const v = k.split('.').reduce((o, part) => (o == null ? o : o[part]), raw);
      if (v !== undefined && v !== null && v !== '') return v;
    }
    return null;
  };

  const name = cleanBusinessName(pick('business_name', 'name', 'title', 'fullName', 'ownerFullName'));
  const handle = normalizeHandle(pick('instagram_handle', 'username', 'instagram', 'instagramUrl', 'instagram_url'));
  const website = normalizeUrl(pick('website', 'url', 'externalUrl', 'external_url', 'site'));
  const domain = normalizeDomain(website);
  const state = normalizeState(pick('state', 'region', 'administrativeArea', 'address.state'));
  const city = normalizeCity(pick('city', 'locality', 'address.city'));
  const products = toProductList(pick('products_services', 'products', 'services', 'menu', 'categories'));

  return {
    business_name: name,
    name_normalized: normalizeBusinessName(name),
    instagram_handle: handle,
    instagram_url: instagramUrl(handle) ?? normalizeUrl(pick('instagram_url', 'instagramUrl')),
    website,
    website_domain: domain,
    email: normalizeEmail(pick('email', 'emails.0', 'contact_email')),
    phone: pick('phone', 'phoneNumber', 'phone_number', 'telephone'),
    phone_e164: normalizePhone(pick('phone', 'phoneNumber', 'phone_number', 'telephone')),
    country: pick('country', 'countryCode') ?? 'US',
    state,
    city,
    postal_code: pick('postal_code', 'postalCode', 'zip'),
    address: pick('address', 'formattedAddress', 'street'),
    latitude: numberOrNull(pick('latitude', 'location.lat', 'lat')),
    longitude: numberOrNull(pick('longitude', 'location.lng', 'lng')),
    category: pick('category', 'categoryName', 'businessCategoryName', 'business_category'),
    bio: pick('bio', 'biography', 'description'),
    website_description: pick('website_description', 'meta_description'),
    products_services: products,
    products_count: products.length || parseCount(pick('products_count', 'productsCount')),
    ig_followers: parseCount(pick('ig_followers', 'followersCount', 'followers', 'follower_count')),
    ig_following: parseCount(pick('ig_following', 'followsCount', 'following')),
    ig_posts: parseCount(pick('ig_posts', 'postsCount', 'posts', 'media_count')),
    ig_is_business: boolOrNull(pick('ig_is_business', 'isBusinessAccount', 'is_business_account')),
    ig_is_private: boolOrNull(pick('ig_is_private', 'private', 'is_private')),
    ig_is_verified: boolOrNull(pick('ig_is_verified', 'verified', 'is_verified')),
    ig_last_post_at: toIsoDate(pick('ig_last_post_at', 'latestPostDate', 'last_post_at')),
    ig_external_url: normalizeUrl(pick('externalUrl', 'external_url', 'bio_link')),
    place_id: pick('place_id', 'placeId', 'fid'),
    source: pick('source', '_source') ?? 'unknown',
    source_search_term: pick('search_term', 'searchString', 'query'),
    raw
  };
}

function numberOrNull(v) {
  const n = Number(v);
  return Number.isFinite(n) ? n : null;
}

function boolOrNull(v) {
  if (v === true || v === false) return v;
  if (v === 'true') return true;
  if (v === 'false') return false;
  return null;
}

/** Products/services arrive as arrays, comma strings or objects. */
function toProductList(value) {
  if (!value) return [];
  let items = [];
  if (Array.isArray(value)) items = value;
  else if (typeof value === 'string') items = value.split(/[,;|\n]/);
  else if (typeof value === 'object') items = Object.values(value);
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const label = collapseWhitespace(
      typeof item === 'string' ? item : (item?.name ?? item?.title ?? item?.label ?? '')
    );
    if (!label || label.length < 2 || label.length > 120) continue;
    const key = label.toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(label);
  }
  return out;
}

// ---- lib/clean.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Cleaning stage: decide whether a normalised lead belongs in the campaign at
// all, and why. Every rejection carries a machine-readable reason so nothing
// disappears silently - the reason lands on leads.disqualified_reason and in
// the activity log.
// ---------------------------------------------------------------------------

const PERSON_NAME_RE = /^[A-Z][a-z]+(?:\s+[A-Z]\.?)?\s+[A-Z][a-z]+$/;

// Words that make a two-word name a business name rather than a person's name.
// "Glow Medspa" and "Radiance Aesthetics" must not read as people.
const BUSINESS_NAME_WORDS = /\b(spa|medspa|salon|clinic|dental|dentistry|studio|shop|store|boutique|brand|co|company|collective|labs?|works|supply|goods|apparel|wear|beauty|aesthetics?|skin|smile|care|health|wellness|fitness|gym|pet|pets|home|robotics|tech|bags?|jewel\w*|watch\w*|eyewear|auto|motors|outfitters)\b/i;

function textOf(lead, field) {
  const value = lead?.[field];
  if (Array.isArray(value)) return value.join(' ');
  return value == null ? '' : String(value);
}

function haystack(lead, fields) {
  return fields.map((f) => textOf(lead, f)).join(' \n ').toLowerCase();
}

function matchesAny(text, terms) {
  const hits = [];
  for (const term of terms ?? []) {
    const t = String(term).toLowerCase().trim();
    if (!t) continue;
    const re = new RegExp(`(^|[^a-z0-9])${t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}([^a-z0-9]|$)`, 'i');
    if (re.test(text)) hits.push(t);
  }
  return hits;
}

/** Personal-account score. Returns { score, signals[] }. */
function personalAccountScore(lead, rules) {
  const cfg = rules?.personal_account_signals;
  if (!cfg) return { score: 0, signals: [] };
  const signals = [];
  let score = 0;

  for (const signal of cfg.signals ?? []) {
    let hit = false;
    if (signal.pattern) {
      const text = textOf(lead, signal.field ?? 'bio').toLowerCase();
      hit = new RegExp(signal.pattern, 'i').test(text);
    } else {
      switch (signal.check) {
        case 'no_website_no_category_no_products':
          hit = !lead.website_domain && !lead.category && (lead.products_services ?? []).length === 0;
          break;
        case 'ig_is_business_false':
          hit = lead.ig_is_business === false;
          break;
        case 'name_is_person_name': {
          const name = String(lead.business_name ?? '').trim();
          // A business word anywhere in the name settles it - so does a match
          // against the niche's own keywords, checked by the caller via flags.
          hit = PERSON_NAME_RE.test(name) && !BUSINESS_NAME_WORDS.test(name);
          break;
        }
        case 'ig_is_private':
          hit = lead.ig_is_private === true;
          break;
        case 'aggregator_link_only':
          hit = !lead.website_domain && isAggregatorDomain(lead.ig_external_url);
          break;
        default:
          hit = false;
      }
    }
    if (hit) {
      score += signal.weight ?? 1;
      signals.push(signal.id);
    }
  }
  return { score, signals };
}

/** Does the lead look like it belongs to this niche? */
function nicheMatch(lead, niche, rules) {
  const cfg = rules?.niche_match ?? { min_keyword_hits: 1, fields: ['business_name', 'bio', 'category'] };
  const text = haystack(lead, cfg.fields ?? []);
  const negatives = matchesAny(text, niche?.negative_keywords ?? []);
  const positives = matchesAny(text, niche?.keywords ?? []);
  const categoryHit = Boolean(
    lead.category && (niche?.keywords ?? []).some((k) => String(lead.category).toLowerCase().includes(String(k).toLowerCase()))
  );
  const hits = categoryHit && !positives.length ? [String(lead.category).toLowerCase()] : positives;
  return {
    matched: hits.length >= (cfg.min_keyword_hits ?? 1) && !(cfg.negative_keyword_drops && negatives.length),
    hits,
    negatives
  };
}

/** Is the lead inside the campaign's geography? */
function locationMatch(lead, campaign, rules) {
  const targeting = campaign?.targeting ?? {};
  const states = (targeting.states ?? []).map((s) => String(s).toUpperCase());
  const cities = (targeting.cities ?? []).map((c) => String(c).toLowerCase());
  const excluded = (targeting.exclude_cities ?? []).map((c) => String(c).toLowerCase());
  const cfg = rules?.location ?? {};

  const leadState = lead.state ? String(lead.state).toUpperCase() : null;
  const leadCity = lead.city ? String(lead.city).toLowerCase() : null;

  if (leadCity && excluded.includes(leadCity)) return { matched: false, reason: 'city_excluded' };

  if (!leadState) {
    if (leadCity && cities.includes(leadCity) && cfg.allow_unknown_state_if_city_matches !== false) {
      return { matched: true, reason: 'city_match_state_unknown' };
    }
    if (cfg.allow_unknown_location_for_ecommerce && campaign?._niche?.business_model === 'ecommerce_brand') {
      return { matched: true, reason: 'unknown_location_allowed_for_ecommerce' };
    }
    return { matched: false, reason: 'location_unknown' };
  }

  if (states.length && !states.includes(leadState)) return { matched: false, reason: 'state_outside_target' };
  if (cities.length && leadCity && !cities.includes(leadCity)) {
    // Inside the right state but a city we did not ask for: keep it, flag it.
    return { matched: true, reason: 'state_match_city_outside_list', soft: true };
  }
  return { matched: true, reason: 'state_match' };
}

/**
 * Main entry point. Returns a decision object; the caller writes it to the DB.
 *   { keep, reasons[], flags{}, lead }
 */
function cleanLead(lead, { campaign = {}, niche = null, rules = {}, now = new Date() } = {}) {
  const reasons = [];
  const flags = {};
  const bounds = rules.absolute_bounds ?? {};

  const name = lead.business_name;
  if (!name) reasons.push('missing_business_name');
  if (name && bounds.max_name_length && name.length > bounds.max_name_length) reasons.push('name_too_long');

  const requiresIg = campaign?.icp?.require_instagram !== false;
  if (requiresIg && !lead.instagram_handle) reasons.push('missing_instagram');

  // Absolute follower/activity sanity bounds (campaign ICP bounds are scored later).
  const followers = lead.ig_followers;
  if (followers != null) {
    if (bounds.min_followers != null && followers < bounds.min_followers) reasons.push('below_absolute_min_followers');
    if (bounds.max_followers != null && followers > bounds.max_followers) reasons.push('above_absolute_max_followers');
  }
  if (bounds.min_posts != null && lead.ig_posts != null && lead.ig_posts < bounds.min_posts) {
    reasons.push('too_few_posts');
  }
  if (
    bounds.max_following_to_followers_ratio &&
    lead.ig_following && followers && followers > 0 &&
    lead.ig_following / followers > bounds.max_following_to_followers_ratio
  ) {
    flags.follow_ratio_suspicious = true;
  }

  // Competitors, agencies, info-products.
  const blockText = haystack(lead, ['business_name', 'bio', 'category', 'website_description']);
  const blocked = matchesAny(blockText, rules.blocked_keywords?.terms ?? []);
  if (blocked.length) {
    reasons.push('blocked_business_type');
    flags.blocked_terms = blocked;
  }

  const fanHits = (rules.fan_account_markers?.patterns ?? []).filter((p) => new RegExp(p, 'i').test(blockText));
  if (fanHits.length) reasons.push('fan_or_parody_account');

  const resellerHits = (rules.reseller_markers?.patterns ?? []).filter((p) => new RegExp(p, 'i').test(blockText));
  if (resellerHits.length) flags.suspected_reseller = true;

  // Personal accounts.
  const personal = personalAccountScore(lead, rules);
  flags.personal_score = personal.score;
  flags.personal_signals = personal.signals;
  if (personal.score >= (rules.personal_account_signals?.threshold ?? 3)) reasons.push('personal_account');

  // Niche.
  if (niche) {
    const match = nicheMatch(lead, niche, rules);
    flags.niche_hits = match.hits;
    flags.niche_negatives = match.negatives;
    if (!match.matched) reasons.push(match.negatives.length ? 'niche_negative_keyword' : 'outside_target_niche');
  }

  // Location.
  const loc = locationMatch(lead, { ...campaign, _niche: niche }, rules);
  flags.location_reason = loc.reason;
  if (!loc.matched) reasons.push('outside_target_location');
  if (loc.soft) flags.city_outside_list = true;

  // Freshness (soft signal only - scoring decides how much it costs).
  const age = daysSince(lead.ig_last_post_at, now);
  if (age != null) flags.days_since_last_post = age;

  return {
    keep: reasons.length === 0,
    reasons,
    flags,
    lead: { ...lead, name_normalized: lead.name_normalized ?? normalizeBusinessName(lead.business_name) }
  };
}

// ---- lib/dedupe.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Deduplication.
// Two walls stop a business being contacted twice:
//   1. this module, in memory, inside a discovery batch;
//   2. resolve_company() + unique(campaign_id, company_id) in the database.
// Both use the same identity keys, in the same priority order.
// ---------------------------------------------------------------------------

const KEY_PRIORITY = ['instagram_handle', 'website_domain', 'place_id', 'phone_e164', 'email', 'name_city'];

/** Every identity key a lead carries, strongest first. */
function identityKeys(lead = {}) {
  const keys = [];
  const handle = normalizeHandle(lead.instagram_handle);
  const domain = normalizeDomain(lead.website_domain ?? lead.website);
  const phone = normalizePhone(lead.phone_e164 ?? lead.phone);
  const email = normalizeEmail(lead.email);
  const name = lead.name_normalized ?? normalizeBusinessName(lead.business_name);

  if (handle) keys.push({ key_type: 'instagram_handle', key_value: handle });
  if (domain) keys.push({ key_type: 'website_domain', key_value: domain });
  if (lead.place_id) keys.push({ key_type: 'place_id', key_value: String(lead.place_id) });
  if (phone) keys.push({ key_type: 'phone_e164', key_value: phone });
  if (email) keys.push({ key_type: 'email', key_value: email });
  if (name) {
    keys.push({
      key_type: 'name_city',
      key_value: `${name}|${(lead.city ?? '').toLowerCase()}|${(lead.state ?? '').toUpperCase()}`
    });
  }
  return keys;
}

/** Levenshtein distance, iterative, two-row. */
function levenshtein(a = '', b = '') {
  if (a === b) return 0;
  if (!a.length) return b.length;
  if (!b.length) return a.length;
  let prev = Array.from({ length: b.length + 1 }, (_, i) => i);
  for (let i = 0; i < a.length; i += 1) {
    const cur = [i + 1];
    for (let j = 0; j < b.length; j += 1) {
      cur[j + 1] = Math.min(prev[j + 1] + 1, cur[j] + 1, prev[j] + (a[i] === b[j] ? 0 : 1));
    }
    prev = cur;
  }
  return prev[b.length];
}

/** 0..1 similarity blending edit distance with token overlap. */
function nameSimilarity(a, b) {
  const x = normalizeBusinessName(a);
  const y = normalizeBusinessName(b);
  if (!x || !y) return 0;
  if (x === y) return 1;
  const edit = 1 - levenshtein(x, y) / Math.max(x.length, y.length);
  const ta = new Set(x.split(' '));
  const tb = new Set(y.split(' '));
  const inter = [...ta].filter((t) => tb.has(t)).length;
  const jaccard = inter / (ta.size + tb.size - inter);
  return Math.max(0, Math.min(1, 0.5 * edit + 0.5 * jaccard));
}

/**
 * Do two leads describe the same business?
 * Strong keys decide on their own. A name match only counts when the location
 * agrees, so "Glow Medspa, Austin" never merges into "Glow Medspa, Miami".
 */
function isLikelySame(a, b, { nameThreshold = 0.92 } = {}) {
  const ka = identityKeys(a);
  const kb = identityKeys(b);
  for (const type of KEY_PRIORITY) {
    if (type === 'name_city') continue;
    const va = ka.find((k) => k.key_type === type)?.key_value;
    const vb = kb.find((k) => k.key_type === type)?.key_value;
    if (va && vb) {
      if (va === vb) return { same: true, matched_on: type, confidence: 1 };
      if (type === 'instagram_handle' || type === 'website_domain') {
        // Conflicting strong keys mean these really are different businesses.
        return { same: false, matched_on: null, confidence: 0, conflict: type };
      }
    }
  }
  const sim = nameSimilarity(a.business_name, b.business_name);
  const sameCity = (a.city ?? '').toLowerCase() === (b.city ?? '').toLowerCase() && Boolean(a.city);
  const sameState = (a.state ?? '').toUpperCase() === (b.state ?? '').toUpperCase() && Boolean(a.state);
  if (sim >= nameThreshold && sameCity && sameState) {
    return { same: true, matched_on: 'name_city', confidence: sim };
  }
  return { same: false, matched_on: null, confidence: sim };
}

/**
 * Collapse a discovery batch.
 * Returns { unique, duplicates } where each duplicate records what it matched.
 * Records are merged field-by-field so the surviving row keeps the best value
 * from every copy (a handle from one source, a phone from another).
 */
function dedupeBatch(leads = [], options = {}) {
  const index = new Map();       // key -> position in unique[]
  const unique = [];
  const duplicates = [];

  for (const lead of leads) {
    const keys = identityKeys(lead);
    let hitIndex = -1;
    let matchedOn = null;

    for (const type of KEY_PRIORITY) {
      const key = keys.find((k) => k.key_type === type);
      if (!key) continue;
      const found = index.get(`${key.key_type}:${key.key_value}`);
      if (found !== undefined) {
        hitIndex = found;
        matchedOn = key.key_type;
        break;
      }
    }

    if (hitIndex === -1) {
      // No exact key hit: fall back to fuzzy comparison against same-city rows.
      for (let i = 0; i < unique.length; i += 1) {
        const verdict = isLikelySame(unique[i], lead, options);
        if (verdict.same) {
          hitIndex = i;
          matchedOn = verdict.matched_on;
          break;
        }
      }
    }

    if (hitIndex === -1) {
      unique.push({ ...lead });
      const position = unique.length - 1;
      for (const key of keys) index.set(`${key.key_type}:${key.key_value}`, position);
    } else {
      duplicates.push({ lead, duplicate_of: unique[hitIndex], matched_on: matchedOn });
      unique[hitIndex] = mergeLeads(unique[hitIndex], lead);
      for (const key of identityKeys(unique[hitIndex])) {
        if (!index.has(`${key.key_type}:${key.key_value}`)) {
          index.set(`${key.key_type}:${key.key_value}`, hitIndex);
        }
      }
    }
  }

  return { unique, duplicates };
}

/** Gap-filling merge: never replace a known value with null, prefer richer lists. */
function mergeLeads(base, incoming) {
  const out = { ...base };
  for (const [field, value] of Object.entries(incoming)) {
    if (value === null || value === undefined || value === '') continue;
    const current = out[field];
    if (current === null || current === undefined || current === '') {
      out[field] = value;
      continue;
    }
    if (Array.isArray(value) && Array.isArray(current)) {
      const merged = [...current];
      const seen = new Set(current.map((v) => String(v).toLowerCase()));
      for (const item of value) {
        const key = String(item).toLowerCase();
        if (!seen.has(key)) { seen.add(key); merged.push(item); }
      }
      out[field] = merged;
      continue;
    }
    if (typeof value === 'number' && typeof current === 'number') {
      // Counts: trust the larger, more complete observation.
      if (/^(ig_followers|ig_following|ig_posts|products_count)$/.test(field)) {
        out[field] = Math.max(current, value);
      }
      continue;
    }
    if (field === 'raw' && typeof value === 'object') {
      out.raw = { ...(current ?? {}), ...value };
    }
  }
  out.products_count = (out.products_services ?? []).length || out.products_count || null;
  return out;
}

